/**
 * New row id: `<prefix>_<uuid v4 without dashes>` (WebCrypto). Ids are generated by callers, not by the database,
 * because a credential's id is part of its encryption AAD (ADR-0007) and must exist before the row does.
 */
export function newId(prefix: 'usr' | 'cred' | 'prj' | 'grt' | 'tok'): string {
  return `${prefix}_${crypto.randomUUID().replaceAll('-', '')}`;
}
